"""Build the complete prose report and a ledger covering each substantive unit."""
import hashlib
import json
from build_source_data import BATCH, read, write


def build():
    mapping = read("RECORD_ID_MAP.json")
    metadata = "# Lilly: Dariot abridgement, illness interpretation and timing\n\nBook II, Chapter XLIV continuation — source audit B02l, 10 October 2026."
    parts = [metadata + "\n"]
    ledger = []
    heading = ""
    def section(title):
        nonlocal heading
        heading = title
        parts.append("\n## " + title + "\n")
    def claim(text, locals_=(), pages=(), files=("RULES.json",), kind="source_and_analysis"):
        text = text.strip()
        refs = [mapping[x] for x in locals_]
        source_note = ""
        if pages:
            source_note = "Original " + ", ".join(f"PDF{p}/printed{p-34}" if p != 888 else "PDF888/errata" for p in pages)
        if refs:
            source_note += ("; " if source_note else "") + ", ".join(x.rsplit(".", 1)[-1] for x in refs)
        if files:
            source_note += ("; " if source_note else "") + ", ".join(f"`{f}`" for f in files)
        complete = text + ("\n\n[" + source_note + ".]" if source_note else "")
        parts.append("\n" + complete + "\n")
        ledger.append({"id": f"C{len(ledger)+1:02d}", "section": heading, "text": complete,
                       "record_ids": refs, "original_pdf_pages": list(pages), "evidence_files": list(files),
                       "claim_type": kind, "text_sha256": hashlib.sha256(complete.encode()).hexdigest()})

    section("Result and exact scope")
    claim("""The **Dariot/Lilly continuation is fully extracted within the admitted span**. It starts at **DARIOT Abridged.** on **PDF292 / printed258**, including the complete italic introduction. It ends on **PDF302 / printed268** with the complete upper paragraph ending “as being necessary to the Judgments of this House,” above the horizontal divider. Every intervening unnumbered section is included. **Chapter XLIV remains incomplete**: the separately headed Hermes text below the divider is the next passage.""", ["A001", "B047"], [292,302], ["SECTION_COVERAGE.json", "READING_RECEIPT.json"])
    claim("""| Measure | Verified source inventory |
|---|---:|
| New source records | 101, R1550–R1650 |
| Cumulative Lilly records | 1,650 |
| Retained Ptolemy records | 1,066 |
| Combined Lilly and retained Ptolemy records | 2,716 |
| General, methodological or illustrative records | 101 |
| Worked-narrative records / dated enquiries / horoscope figures | 0 / 0 / 0 |
| Editorial coverage units / admitted main-span PDF pages | 9 / 11 |
| Typed register entries | 42 |
| Retained limits or anomalies / source-resolved entries | 36 / 6 |
| Actual distinct focused tests passed | 20 |

The 101 records are an extraction inventory, not 101 independent predictions. The register counts typed observations, not errors in the source. Several entries concern interpretation, missing implementation conventions or evidence limits; a confirmed glyph can still belong to a sentence with unresolved grammar.""", files=["COUNTS.json", "UNRESOLVED.json", "TEST_RUN_SUMMARY.json", "PTOLEMY_COUNT_RECEIPT.json"], kind="inventory_and_count_semantics")
    coverage = read("SECTION_COVERAGE.json")["sections"]
    table = "| Editorial coverage unit | Original PDF pages | Records |\n|---|---|---|\n"
    for s in coverage:
        p = s["pdf_pages"]
        table += f"| {s['title']} | {p[0]}" + (f"–{p[-1]}" if len(p)>1 else "") + f" | {s['record_ids'][0].rsplit('.',1)[-1]}–{s['record_ids'][-1].rsplit('.',1)[-1]} |\n"
    claim(table+"\nThese nine units organize a continuous source span. They do not constitute nine newly completed numbered chapters. Four earlier timing records are retained for comparison without being counted again.", files=["SECTION_COVERAGE.json", "RETAINED_SOURCE_EXCERPTS.json"], kind="coverage_inventory")
    claim("""The work is a historical source audit. No patient is assessed and no treatment, survival probability or personal forecast is generated. The historical disease, humour, spirit and mind terminology is preserved without claiming equivalence to modern diagnoses. The data and helpers remain reference material outside the prediction runtime. **Predictive accuracy remains unevaluated.**""", files=["RULES.json", "COUNTS.json", "lilly_dariot_reference.py"], kind="evidence_and_implementation_scope")

    section("1. Whose words are being read")
    claim("""Lilly's italic introduction says that he has favoured Dariot's method of judgment in sickness and is offering the following material to the reader. The heading therefore establishes an abridgement context; it does not make every following first-person sentence a quotation from Dariot. Explicit marginal attributions and first-person transitions identify some local contributions. Other stretches remain uncertain at sentence level. The extraction records those differences, including reported material from “the Ancients,” rather than assigning a single author to the entire block.""", ["A001", "A007", "A021", "A022", "B041"], [292,293,295,301], ["RULES.json", "UNRESOLVED.json"])
    claim("""This batch reads Lilly's 1647 English presentation. It does not claim a comparison with an independently selected original edition of Dariot. The final upper paragraph announces the forthcoming Hermes material and explains Lilly's editorial reasons for including it: variety of teaching, the burden of sickness, the desirability of health, the writer's reported esteem, and its relevance to judgments of the sixth house. Those are Lilly's reported editorial and reception claims; they do not establish ancient authorship or independent clinical corroboration.""", ["B046", "B047"], [302], ["RULES.json", "SOURCES.md", "UNRESOLVED.json"])

    section("2. Sickness and outward causes retain their prerequisites")
    claim("""The first sickness rules distinguish the **querent's significator** from a disease significator. The illustrative example puts Mars, described as hot and dry and ruling the ascendant, in cold and moist Cancer. Cadency is a separately stated alternative, with the sixth house emphasized. Another sentence gathers adverse conditions for a diurnal significator below the earth; its mixture of conjunctions and alternatives does not supply unambiguous computational parentheses. The nocturnal extension says to make the necessary corresponding adjustments without enumerating a mechanical inversion.""", ["A002","A003","A004","A005","A006"], [293])
    claim("""Lilly then describes his own practice when a question was brought with or without urine. His no-sickness chain begins with an ascendant that is **not** afflicted, followed by adverse lord conditions introduced with “or.” Later alternatives include favourable or unafflicted configurations. The printed syntax leaves the reach of the negative unsettled. The extraction retains the entire chain: alternative judgments of no present or ensuing sickness are accompanied by the explanation that suspicion arose from a sudden bodily distemper soon rectified. It adds no unprinted second negative and chooses no executable polarity.""", ["A007","A008"], [293,294], ["RULES.json", "UNRESOLVED.json", "TEXTUAL_CHECKS.json"])
    claim("""The inward-cause discussion uses the significator's disposition, sign, house and **good or ill** configuration with malevolent planets. It adds that any planet **may** act malignantly here through such roles as lord of the sixth, eighth or twelfth. This is a context-sensitive role statement. Neither a permanently favourable classification for Jupiter or Venus nor an assumption that only bad aspects matter reproduces all of this wording.""", ["A009","A010"], [293,294])
    claim("""In the outward-cause example, the ascendant lord is strong in essential dignity, swift and in a good house. The subsequent square or opposition of Saturn or Mars retains exclusions applying to both planets: **neither Saturn nor Mars is the sixth lord or the Moon's dispositor**. Lilly distinguishes being unwell from being perfectly sick, then directs attention to the afflictor's occupied or ruled house. The second-house example additionally requires no inward cause: application concerns current money want, whereas separation concerns a recent loss. The larger harm assigned to opposition belongs to this local example and is not a universal aspect weight.""", ["A011","A012","A013","A014","A015","A016","A017"], [293,294])
    claim("""The fifth- and seventh-house examples contain further qualifications. Games require the person's capacity for them; the youth/distemper parenthesis in the fifth-house sentence has uncertain reach. The seventh-house passage gives several alternative sources of discontent and reciprocal husband/wife references. The youth continuation concludes that no sickness follows. These are general or hypothetical interpretations, with a later broad claim about Lilly's customary practice. They are not separately documented patient histories with observed endpoints.""", ["A018","A019","A020","A021"], [294,295])

    section("3. Disease qualities: exact actors, modifiers and glyphs")
    claim("""The planetary catalogue follows an instruction to erect the figure and select the disease significator. A planet's mere presence is therefore insufficient to transfer every catalogue consequence into a chart. Saturn's tedious diseases, Jupiter's liver and blood descriptions, Mars's fever material, and the following Sun, Venus and Mercury statements retain that local context and their distinct conditions. Historical claims about bloodletting, sweating or other causes remain documentary content; no treatment rule is implemented.""", ["A022","A023","A024","A033","A036","A039","A040","A048","A050","A053"], [295,296,297])
    claim("""The difficult Saturn sentence on printed261 shows **Leo or Scorpio with South Node or North Node**. The two nodal glyphs are identifiable. The reach of “with” remains unsettled: it might qualify Scorpio alone or both sign alternatives. Combustion and violent-star alternatives are also retained. The next poisoning statement is both tentative and conditional on **prior suspicion**. It must not be treated as newly established poisoning from the chart alone.""", ["A025","A026"], [295], ["RULES.json", "UNRESOLVED.json", "TEXTUAL_CHECKS.json"])
    claim("""The Saturn material uses modifiers that should survive extraction. Fire-sign fevers are described as **usually** occurring. The cold/moist account is said to be more assured when Venus or the Moon shares disease signification, while the reach of the following descriptive continuation remains open. The text reads “vitious,” not an editorial substitution of “viscous.” The fixed-sign passage gives **Taurus, Leo and Aquarius as examples** after naming the class. It does not print Scorpio in that list, but “as in” does not establish that Scorpio is excluded from the class.""", ["A027","A028","A029","A030"], [295], ["RULES.json", "UNRESOLVED.json", "TEXTUAL_CHECKS.json"])
    claim("""The common-sign Mars passage distinguishes a disease appearing to depart from its eventual outcome. At that apparent departure, **Saturn having signification and being in aspect with good planets** is the stated favourable condition. The source does not additionally require that aspect itself to be good. The alternative involving Saturn with the eighth or sixth lord says one **may** expect death; it is not an observed death. Elsewhere, melancholy is conditional on Saturn's involvement, while the possessive in “Mars in any of his dignities” remains uncertain. The planet opening printed263 is Mars, continuing the fever sequence.""", ["A041","A042","A043","A044","A045","A047"], [296,297], ["RULES.json", "UNRESOLVED.json", "TEXTUAL_CHECKS.json"])
    claim("""The Sun's affliction statement is tied to the first lying down and includes an antiscion alternative for Saturn. The following Mars clause refers back to the aforesaid aspects, leaving the exact reach of that shorthand open. Venus in a fiery sign is associated with a one-day fever, but the next variant says Mars joins in signification; that is not an expressly stated physical conjunction, and the duration is not repeated for the variant. Mercury requires both misfortune and disease authorship. The final ninth-lord-in-sixth occult-cause sentence again requires existing mistrust.""", ["A048","A049","A050","A051","A052","A053","A054"], [297])
    claim("""The targeted errata check found two entries within the admitted printed-page range: **printed261 line23, “usually,”** and **printed262 line33, “returning.”** The corresponding body readings already agree. The original errata page provides no identified correction within that range for the other retained negative or grammatical scope problems. This is a targeted check of the printed errata, not a collation of all editions.""", ["A027","A045"], [295,296,888], ["TEXTUAL_CHECKS.json", "UNRESOLVED.json"])

    section("4. Body location and mind/body roles cannot be flattened")
    claim("""The first side rule connects an unfortunate or afflicted sixth lord above the earth with the right and upper parts. A later first-person claim adds a masculine-planet condition. These are separately worded rules; the extra condition should not be silently imported backwards. Another sentence literally says **“superiour and fore-part”** for an alternative that includes the sixth lord below the earth. That reading is retained without changing superior to inferior. The nocturnal-sign continuation and the inheritance of some earlier conditions remain explicit interpretation limits.""", ["B001","B002","B003","B005"], [297], ["RULES.json", "UNRESOLVED.json", "TEXTUAL_CHECKS.json"])
    claim("""The left-side rule has two actors: the disease significator is in a feminine sign and aspects a feminine planet, while that other planet is in a feminine sign **or house**. The relevant house classification is not supplied in the passage. The degree instruction concerns the upper, middle or lower part of **the member**, using few, middle and lower degrees. It does not define numerical bins, decans or a whole-body scale. Its inherited conditions and the numerical meaning of lower remain open.""", ["B004","B006"], [297,298])
    claim("""The mind/body discussion repeatedly changes which role is used. The introductory spirit group contains the ascending sign, Moon and lord of the Sun's house; the member group contains the ascendant lord and Moon's dispositor. One later all-afflicted condition uses the **Sun itself** with ascendant and Moon. Another all-or-two condition uses the **lord of the Sun's house**. A further comparison uses the **dispositor of the ascendant lord**, a second-order role. These are not interchangeable labels. Counting roles also requires distinguishing them from the number of physical planetary bodies they happen to identify.""", ["B007","B008","B009","B010","B016"], [298,299], ["RULES.json", "REFERENCE_TABLES.json", "UNRESOLVED.json"])
    claim("""The text reports that many astrologians say Saturn foreshows **or causes** melancholy, preserving an unresolved causal alternative. Its Saturn sequence contains several role, placement and relation branches. The following contrast prints **Jupiter** and says it **never** oppresses the mind but the body. Those words are retained, while the amount of the preceding Saturn condition list intended to transfer is unstated. No modern causal or psychiatric claim is inferred from this historical account.""", ["B012","B013","B014"], [298], ["RULES.json", "TEXTUAL_CHECKS.json", "UNRESOLVED.json"])
    claim("""One adverse Mars sentence explicitly lists **sextile, square and opposition**. It is not silently repaired to conjunction, square and opposition. The printed wording about being oppressed in the twelfth also leaves its attachment to the alternatives unresolved. Elsewhere, a malevolent aspect to the ascendant is accompanied by the explicit exclusion **not to the Moon** and by an additional afflicted Sun-sign lord. Comparative statements about degrees being more afflicted than their lords, or the reverse, supply no strength metric, tie rule or numerical aggregation.""", ["B017","B018","B019"], [299], ["RULES.json", "TEXTUAL_CHECKS.json", "UNRESOLVED.json"])
    claim("""The remaining mind/body clauses preserve their own combinations rather than harmonizing them into one global classifier: unimpeded rulers can matter alongside afflicted ascendant and Moon; exalted Sun and ascendant lord can coexist with a debilitated Moon dispositor; plural solar-affliction conditions have uncertain distribution; and a later freedom-from-Saturn/Mars phrase has an uncertain subject. “Usually” remains in the Sun-related character account. Venus is not given an extra affliction prerequisite merely because the following Mercury sentence expressly has one.""", ["B011","B015","B020","B021","B022","B023","B024"], [298,299])

    section("5. Natal, mundane and lunar references remain distinct")
    claim("""The natal callback begins **if the nativity can be procured**. It considers natal degrees and eclipses or great conjunctions near the sickness, without fixing the degree-versus-sign match or numerical nearness threshold. The following danger statement also mentions the sign of the eighth house of the **yearly revolution of the World** falling on natal angles, particularly the ascendant. That reference frame must not be relabelled as the natal or horary eighth house. A separate sign callback allows first sickness **or** the patient's demand, without stating the later critical-day hierarchy in that sentence.""", ["B025","B026","B027"], [299,300])
    claim("""The close Sun–Moon statement requires more than distance. It specifies a separation **not above six degrees**, with the Moon not yet passed the Sun and the exact conjunction not yet perfected. Aries or Leo mitigates the stated ill omen but does not remove it. The following sentence says **at twelve degrees** there is little danger. It does not say twelve degrees or more, does not say no danger, and does not supply an interpolation between six and twelve. Its phase condition is not restated. These distinctions are documented, without constructing a clinical risk threshold.""", ["B028","B029"], [300], ["RULES.json", "REFERENCE_TABLES.json", "UNRESOLVED.json"])

    section("6. Critical days: a local origin and three angles")
    claim("""The critical-day procedure first asks for the hour at which the sick person took bed, as nearly as it can be obtained. **If that hour cannot be had**, it uses the first time the physician was asked to judge. The Moon's motion is then corrected to the chosen hour. This local two-stage statement is kept separate from the earlier opening procedure on printed243, which also discussed carrying urine and alternatives involving the physician's first access or contact. The later passage does not silently overwrite the earlier one for every question context.""", ["B030","B031"], [300,277], ["RULES.json", "RETAINED_SOURCE_EXCERPTS.json", "REFERENCE_TABLES.json"])
    claim("""For **acute, not chronic**, diseases, Lilly identifies changes near the times when the Moon has moved **45°, 90° or 135°** from that first place. This passage does not provide a 180° point, a general sequence of all multiples of 45°, a fixed number of days, or a tolerance for “near.” The helper consequently returns three angular targets only. A corrected starting longitude, applicable illness class and selected origin must be supplied; otherwise the result remains unresolved or not applicable.""", ["B031","B032"], [300], ["RULES.json", "lilly_dariot_reference.py", "REFERENCE_TABLES.json"])
    claim("""A synthetic arithmetic example uses a starting longitude of **350°15′**:

| Stated displacement | Calculation around the zodiac | Target longitude |
|---|---|---|
| 45° | 350°15′ + 45° − 360° | 35°15′ |
| 90° | 350°15′ + 90° − 360° | 80°15′ |
| 135° | 350°15′ + 135° − 360° | 125°15′ |

These are modular angle calculations in integer arcseconds. The starting value is a test example, not an extracted Lilly chart. No ephemeris or calendar date is supplied, and none of these targets is an evaluated clinical prediction.""", ["B032"], [300], ["ARITHMETIC_CHECKS.json", "lilly_dariot_reference.py", "TEST_RUN_SUMMARY.json"], kind="source_and_arithmetic")
    claim("""The direction of the claimed change depends on further conditions. The favourable crisis statement requires **both a good aspect and a benevolent planet**. An ill aspect of the sixth or eighth lord is associated with worsening, increased pain and little good from medicine. Lilly's later first-person recollection about hard lunar aspects includes the planet that earlier afflicted the relevant places, the sixth lord or a planet in the sixth. It supplies no case denominator, and the precise chart endpoints and reach of the earlier acute-only limit remain unsettled.""", ["B033","B034","B035"], [300,301])
    claim("""The next statement is an act of prognosis: Lilly says he pronounces comfort and some interval of ease for specified lunar sextiles or trines to the first, eleventh, ninth or tenth lord. That wording is not a verified recovery endpoint. The ascendant-lord/Sun clause concerns relief of mind and excludes power **or** dominion in the disease; the pronoun most naturally points to the Sun, but another reading is retained. It is not converted into an unconditional bodily cure.""", ["B036","B037"], [301])

    section("7. Recovery timing retains discretion and alternative outcomes")
    claim("""The recovery-time question starts **after recovery has already been judged**, and when the querent asks when. Lilly counts degrees between the ascendant lord and the benefic involved in the aspect, considers the houses and signs of both, and joins the quality of the disease to discretion. The exact degree measure—raw distance or a perfected-aspect measure—is not fully specified here. A favourable aspect alone must not be treated as proving recovery.""", ["B038"], [301])
    claim("""For moveable signs, days are the **ordinary** interpretation; Lilly expresses more certainty when the planets are **both swift and angular**. The stated event is amendment, which need not mean complete cure. For common signs he expressly declines a mechanical choice of months, weeks or days: the illness and what duration is feasible must be considered. His report of the Ancients immediately afterward supplies alternatives, not a single universal scale.""", ["B039","B040","B041"], [301])
    claim("""| Source category | Reported time options | House correspondence |
|---|---|---|
| Moveable sign | Days | Angular |
| Common sign | Weeks or months | Succedent |
| Fixed sign | Months or years | Cadent |

The table gives the Ancients' sign associations and the subsequent house equivalences. The text supplies no priority when the actual sign and house point to different rows. Lilly also asks for the Moon's speed, sign and quality **together with the principal significators**, mixing the considerations. The reference helper therefore displays the sign and house options separately and leaves the selected unit and date empty.""", ["B041","B042","B043"], [301,302], ["RULES.json", "REFERENCE_TABLES.json", "lilly_dariot_reference.py"])
    claim("""A later ingress rule says the ascendant lord leaving the sign occupied at question time and entering an essential dignity is associated with **recovery or sensible improvement**. It does not additionally require the outgoing sign to have been a debility. The numerical sixth-cusp example is different: **28° on the sixth cusp and a common sign** leads Lilly to say the disease will **vary in less than two weeks**. The record preserves the exact condition and strict upper bound. It does not turn 28 into 28-or-more, “vary” into recover, or the hypothetical illustration into a dated case.""", ["B044","B045"], [302], ["RULES.json", "REFERENCE_TABLES.json", "UNRESOLVED.json"])
    claim("""The earlier timing passage on printed249 selects among months, weeks and days according to **the sign's nature and quality**. The new recovery discussion on printed267 separately considers **the disease's quality or nature and the practitioner's discretion**. These distinct selectors support keeping the selection context explicit; they do not establish a new combined numerical algorithm. The final promise to give a figure or two refers forward; no such figures occur inside this admitted continuation, so the promise adds neither two charts nor two completed cases to the present inventory.""", ["B038","B040","B043","B046"], [283,301,302], ["RULES.json", "RETAINED_SOURCE_EXCERPTS.json", "COUNTS.json"])

    section("8. Verification, remaining limits and use of the packet")
    claim("""The original 894-page PDF's SHA256 was recomputed for this batch. The packet's 14-page source window contains the eleven main-span pages plus the errata and two earlier timing pages. Every copied page was rendered and compared with the corresponding original: dimensions and pixels matched. Full page context is intentionally visible; the preceding completed paragraph and the next Hermes opening remain outside the newly extracted span. Eleven selected original-page crops support difficult readings. The packet does not duplicate every producer's redundant page render.""", files=["SOURCE_IDENTITY.json", "SOURCE_WINDOW_VERIFICATION.json", "SOURCE_IMAGE_MANIFEST.json", "WORKER_HANDOFF_COPY_RECEIPT.json"], kind="source_material_verification")
    claim("""The two source readers produced 54 and 47 frozen records. Root read the entire original span and checked the source clauses before compilation. A separate fresh context first froze its own full-span source-only notes before seeing the candidate. The defined acceptance procedure is one exhaustive check of the source, all report-ledger units and any missed report claims, followed by at most two checks of changed items if needed. This is separated same-family diagnostic review, not cross-family review, expert adjudication or independent empirical validation. Final diagnoses and their dispositions belong in the review evidence, rather than being inferred from the fact that a reviewer was assigned.""", files=["READING_RECEIPT.json", "WORKER_HANDOFF_COPY_RECEIPT.json", "REVIEW_POLICY.json", "independent_review/source_first/SOURCE_FIRST_FREEZE.json"], kind="actual_method_and_review_policy")
    claim("""The actual focused run passed **20 tests**, with no failures, errors or skips. The suite checks contiguous source IDs, complete declared-page and section mappings, retained-index continuity, issue/reference links, missing versus zero inputs, source-time priority, the three lunar angles including zodiac wrap, acute/chronic scope, and unresolved timing choices. Its receipt binds the tested files by hash. These tests establish the specified source-data and bounded calculation behavior; they do not establish disease prediction or treatment efficacy. The required extracted-archive run repeats this same suite and must add **zero** to the distinct-test count.""", files=["TEST_RUN_SUMMARY.json", "TEST_RUN.log", "test_lilly_dariot.py", "run_verification.py"], kind="test_results_and_scope")
    claim("""The remaining limitations include sentence-level attribution, negative and modifier scope, historical vocabulary, local significator identities, repeated planetary bodies, missing strength metrics, unspecified angular or temporal tolerances, time-unit discretion, and the absence of independent clinical endpoints. The six resolved register entries concern two clearly readable source constructions and four root glyph/errata checks. A resolution is confined to its identified reading; it does not license a wider repair or make the historical claim empirically true.""", files=["UNRESOLVED.json", "TEXTUAL_CHECKS.json", "COUNTS.json"], kind="limitations_inventory")
    claim("""Use `RULES.json` for the full 101-record inventory; each record retains its source locator, attribution evidence, conditions, outcomes, exceptions, dependencies, uncertainties and implementation limits. `REFERENCE_TABLES.json` is a compact documentary view. `UNRESOLVED.json` preserves the typed issues and resolutions. `SOURCE_WINDOW_VERIFICATION.json` maps the original pages. `run_verification.py` runs the standalone standard-library suite after extraction. Publication, preservation, archive and owner-delivery receipts are separate evidence of those operations; they are not substituted for source review or predictive validation.""", files=["RULES.json", "REFERENCE_TABLES.json", "UNRESOLVED.json", "SOURCE_WINDOW_VERIFICATION.json", "run_verification.py"], kind="packet_usage")
    section("Exact continuation boundary")
    claim("""Next: **PDF302 / printed268, below the horizontal divider**, beginning **“Hermes Trismegistus upon the first Decumbiture of the Sick.”** Include that heading and the **complete opening paragraph** beginning “The heavenly Rayes or Influences proceeding and emitted from the seven Planets,” then continue on PDF303. The entire upper bridge is already complete. The next source record is **R1651**. Chapter XLIV, the rest of Lilly and the wider multi-author audit remain open.""", ["B047"], [302], ["SECTION_COVERAGE.json", "LILLY_SOURCE_EXTRACTION_INDEX_SNAPSHOT.json", "COUNTS.json"])
    # MC-01: bind the existing title/byline without renumbering C01-C41.
    ledger.append({"id": "C42", "section": "Document metadata", "text": metadata,
        "record_ids": [mapping["A001"], mapping["B047"]], "original_pdf_pages": [292,302],
        "evidence_files": ["SECTION_COVERAGE.json", "TASK_ENVELOPE.json"],
        "claim_type": "document_metadata", "text_sha256": hashlib.sha256(metadata.encode()).hexdigest()})
    report = "".join(parts)
    (BATCH/"AUDIT_REPORT.md").write_text(report, encoding="utf-8")
    write("CLAIM_LEDGER.json", {"batch": "B02l", "report_file": "AUDIT_REPORT.md",
        "report_sha256": hashlib.sha256(report.encode()).hexdigest(), "verification_item_count": len(ledger),
        "unit_semantics": "Each item binds a complete paragraph or table, including every subclaim and qualification. This is not a count of independent predictions.",
        "whole_report_coverage_requirement": "Check every item and scan the complete report for factual claims absent from this ledger. Separate source, arithmetic, inventory, procedure and evidence-scope diagnoses.",
        "items": ledger})
    print(json.dumps({"report_characters": len(report), "report_words": len(report.split()), "claim_units": len(ledger)}))


if __name__ == "__main__":
    build()
